item.command:
/bin/zsh -lc "node --input-type=module <<'RELAYER_GRAPH_PROGRAM'
import { RelayerGraphClient } from 'file:///Users/[redacted]/.codex/worktrees/attached-navigation/relayer-graphcomplete/packages/graph-client/dist/index.js';
const graph = RelayerGraphClient.fromEnv();
const interaction = await graph.getNode(31);
const neighbors = await graph.getNeighbors(31);
const input = await graph.getInteractionInput();
const presentation = await graph.getNodePresentation(22);
let current;
try { current = await graph.getCurrent(); } catch (error) { current = { unavailable: true, code: error?.code, status: error?.status }; }
console.log(JSON.stringify({ interaction, neighbors, input, presentation, current }, null, 2));
RELAYER_GRAPH_PROGRAM"

