item.command:
/bin/zsh -lc "node --input-type=module <<'RELAYER_GRAPH_PROGRAM'
import {
  RelayerGraphClient, NodeObject, EdgeObject, NodePlacementObject,
  LayerLayoutObject, LayerObject, html, css, detailCapability,
} from 'file:///Users/[redacted]/.codex/worktrees/attached-navigation/relayer-graphcomplete/packages/graph-client/dist/index.js';

const graph = RelayerGraphClient.fromEnv();
const interactionNode = 31;
await graph.getNode(interactionNode);
await graph.getNeighbors(interactionNode);
await graph.getInteractionInput();
const presentation = await graph.getNodePresentation(22);
const persistent = presentation.node;
if (
  persistent.clientKey "'!== '"'launch-decision' ||
  persistent.title "'!== '"'Launch decision' ||
  persistent.detail "'!== '"'Release when error rate stays below 1% and rollback is ready.'
) throw new Error('Launch decision identity or semantic text changed');

const actionByKey = new Map(presentation.actions.map((action) => [action.clientKey, action]));
const originalInvoke = actionByKey.get('draft-rollout-recommendation');
const originalReadiness = actionByKey.get('launch-release-readiness-reference');
const originalChecklist = actionByKey.get('launch-readiness-checklist-expand');
if (
  presentation.actions.length "'!== 3 ||
  !originalInvoke || originalInvoke.kind !== '"'invoke' || originalInvoke.sourceLayerId "'!== 7 || originalInvoke.sourceLayerClientKey !== '"'release-readiness-root' ||
  "'!originalReadiness || originalReadiness.kind !== '"'navigate' || originalReadiness.relation "'!== '"'reference' || originalReadiness.sourceLayerId "'!== null ||
  !originalChecklist || originalChecklist.kind !== '"'navigate' || originalChecklist.relation "'!== '"'expand' || originalChecklist.sourceLayerId "'!== null
) throw new Error('"'Expected three accepted controls with their canonical provenance');

const releaseSummary = new NodeObject(
  'clipboard-check',
  'Release summary',
  'This synthetic walkthrough gates release on an error rate below 1% and a ready rollback path.',
  'concept',
  'native-release-summary',
);
const nextSteps = new NodeObject(
  'arrow-right-circle',
  'Next steps',
  'Confirm both readiness checks, then make the release decision; no external customer facts are asserted.',
  'concept',
  'native-next-steps',
);
const summaryEdge = new EdgeObject([releaseSummary, nextSteps], 'native-summary-next-steps-edge');
const responseRoot = new LayerObject(
  [releaseSummary, nextSteps],
  [summaryEdge],
  new LayerLayoutObject([
    new NodePlacementObject(releaseSummary, 0.30, 0.50),
    new NodePlacementObject(nextSteps, 0.70, 0.50),
  ]),
  'native-final-readiness-root',
);
responseRoot.defaultNode = releaseSummary;

const finalReadiness = {
  kind: 'navigate',
  relation: 'reference',
  label: 'Final readiness',
  target: responseRoot,
  icon: 'clipboard-check',
  variant: 'wide',
  clientKey: 'native-final-readiness-reference',
};

const nodeCss = css"'`
  .card { display: grid; gap: 1rem; padding: 1.3rem; border: 1px solid; border-radius: 0.95rem; max-width: 40rem; box-sizing: border-box; }
  .eyebrow { font-size: 0.74rem; font-weight: 700; letter-spacing: 0.08rem; text-transform: uppercase; }
  h2 { margin: 0; font-size: 1.4rem; line-height: 1.2; }
  p { margin: 0; line-height: 1.58; }
  .criteria { display: grid; grid-template-columns: 1fr 1fr; gap: 0.7rem; }
  .criterion { display: grid; gap: 0.2rem; padding: 0.78rem; border: 1px solid; border-radius: 0.7rem; }
  .criterion strong { font-size: 0.92rem; }
  .criterion small { font-size: 0.76rem; }
  .sequence { display: grid; gap: 0.55rem; }
  .step { display: grid; grid-template-columns: auto 1fr; gap: 0.7rem; align-items: center; padding: 0.7rem; border: 1px solid; border-radius: 0.7rem; }
  .number { display: grid; place-items: center; width: 1.8rem; height: 1.8rem; border-radius: 1rem; font-weight: 800; }
  [data-relayer-theme="light"] .card { color: #172126; background-color: #fbfcfd; border-color: #d6dee2; box-shadow: 0 8px 22px rgba(25,38,45,0.08); }
  [data-relayer-theme="light"] .eyebrow, [data-relayer-theme="light"] .criterion small { color: #5a6a70; }
  [data-relayer-theme="light"] .criterion, [data-relayer-theme="light"] .step { background-color: #f2f7f5; border-color: #c5d9d1; }
  [data-relayer-theme="light"] .number { color: #ffffff; background-color: #246150; }
  [data-relayer-theme="dark"] .card { color: #edf3f4; background-color: #141a1d; border-color: #364449; box-shadow: 0 8px 22px rgba(0,0,0,0.28); }
  [data-relayer-theme="dark"] .eyebrow, [data-relayer-theme="dark"] .criterion small { color: #a8b8bd; }
  [data-relayer-theme="dark"] .criterion, [data-relayer-theme="dark"] .step { background-color: #192522; border-color: #3d6156; }
  [data-relayer-theme="dark"] .number { color: #102019; background-color: #93d5bd; }
`;
releaseSummary.detailAuthoring.setComponent('"'main', html"'`<main class="card">
  <div class="eyebrow">Synthetic qualification</div>
  <h2>Release summary</h2>
  <p>The release gate is intentionally bounded to two readiness conditions.</p>
  <div class="criteria" aria-label="Release criteria">
    <div class="criterion"><strong>Error rate</strong><small>Stays below 1%</small></div>
    <div class="criterion"><strong>Rollback</strong><small>Ready before release</small></div>
  </div>
</main>`, nodeCss);
nextSteps.detailAuthoring.setComponent('"'main', html"'`<main class="card">
  <div class="eyebrow">Decision sequence</div>
  <h2>Next steps</h2>
  <p>Use the synthetic checks in order; no external customer facts are included.</p>
  <div class="sequence">
    <div class="step"><span class="number">1</span><span>Check the error-rate threshold.</span></div>
    <div class="step"><span class="number">2</span><span>Confirm rollback readiness.</span></div>
    <div class="step"><span class="number">3</span><span>Make the release decision.</span></div>
  </div>
</main>`, nodeCss);

await graph.checkpointNodeDetail(releaseSummary);
await graph.checkpointNodeDetail(nextSteps);
await graph.submitNode(releaseSummary);
await graph.submitNode(nextSteps);
await graph.createEdge(summaryEdge);
await graph.submitLayer(responseRoot);

const replacement = new NodeObject(persistent.icon, persistent.title, persistent.detail, persistent.kind, persistent.clientKey);
const canonicalInvokeLayer = new LayerObject(
  [replacement],
  [],
  new LayerLayoutObject([new NodePlacementObject(replacement, 0.5, 0.5)]),
  originalInvoke.sourceLayerClientKey,
);
const invokeBinding = {
  kind: '"'invoke',
  label: originalInvoke.label,
  interactionText: originalInvoke.interactionText,
  sourceLayer: canonicalInvokeLayer,
  icon: originalInvoke.icon,
  variant: originalInvoke.variant,
  clientKey: originalInvoke.clientKey,
};
const readinessBinding = {
  kind: 'navigate',
  relation: originalReadiness.relation,
  label: originalReadiness.label,
  target: originalReadiness.targetLayerId,
  icon: originalReadiness.icon,
  variant: originalReadiness.variant,
  clientKey: originalReadiness.clientKey,
};
const checklistBinding = {
  kind: 'navigate',
  relation: originalChecklist.relation,
  label: originalChecklist.label,
  target: originalChecklist.targetLayerId,
  icon: originalChecklist.icon,
  variant: originalChecklist.variant,
  clientKey: originalChecklist.clientKey,
};

replacement.detailAuthoring.setComponent('main', html"'`<main class="decision-card">
  <div class="eyebrow">Synthetic release gate</div>
  <h2>Launch decision</h2>
  <p class="summary">Release when error rate stays below <strong>1%</strong> and rollback is ready.</p>
  <div class="status"><span class="status-mark">2</span><span><strong>Readiness status</strong><small>Two explicit checks define the launch gate.</small></span></div>
  <div class="controls" aria-label="Launch decision actions">
    <button class="control primary" gc=${detailCapability.invoke('"'launch-rollout-control', invokeBinding)}>Draft rollout recommendation</button>
    <button class=\"control secondary\" gc="'${detailCapability.reference('"'launch-release-readiness-control', readinessBinding)}>Release readiness</button>
    <button class=\"control secondary\" gc="'${detailCapability.expand('"'launch-readiness-checklist-control', checklistBinding)}>Readiness checklist</button>
    <button class=\"control accent\" gc="'${detailCapability.reference('"'native-final-readiness-control', finalReadiness)}>Final readiness</button>
  </div>
</main>"'`, css`
  .decision-card { display: grid; gap: 1rem; padding: 1.35rem; border: 1px solid; border-radius: 1rem; max-width: 42rem; box-sizing: border-box; }
  .eyebrow { font-size: 0.74rem; font-weight: 700; letter-spacing: 0.08rem; text-transform: uppercase; }
  h2 { margin: 0; font-size: 1.45rem; line-height: 1.2; }
  .summary { margin: 0; font-size: 1.04rem; line-height: 1.58; }
  .status { display: grid; grid-template-columns: auto 1fr; gap: 0.75rem; align-items: center; padding: 0.8rem; border: 1px solid; border-radius: 0.75rem; }
  .status-mark { display: grid; place-items: center; width: 2.1rem; height: 2.1rem; border-radius: 1.1rem; font-weight: 800; }
  .status span:last-child { display: grid; gap: 0.18rem; }
  .status small { font-size: 0.78rem; }
  .controls { display: grid; grid-template-columns: 1fr 1fr; gap: 0.65rem; }
  .control { width: 100%; padding: 0.8rem 0.9rem; border: 1px solid; border-radius: 0.65rem; font: inherit; font-weight: 700; }
  .control:hover { opacity: 0.88; }
  .control:focus-visible { outline: 3px solid; outline-offset: 2px; }
